// Iron interface uses the existing storage and journal; no data migration required.
const journalWorkout = workout;
const journalBind = bind;
let restDeadline = 0;
let restPaused = true;
let lastGain = 0;

function bellMark(){return '<svg viewBox="0 0 48 56" aria-hidden="true"><path d="M14 22V15a10 10 0 0 1 20 0v7" fill="none" stroke="currentColor" stroke-width="5"/><path d="M24 20C3 20 2 51 24 52c22-1 21-32 0-32" fill="currentColor"/></svg>'}
function swingArt(){return `<svg class="swing-art" viewBox="0 0 300 300" aria-hidden="true"><path d="M38 240A180 180 0 0 0 258 55" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="M50 255A195 195 0 0 0 274 55" fill="none" stroke="currentColor" stroke-width="1" opacity=".3"/><path d="M65 25 230 128" stroke="currentColor" stroke-dasharray="3 7" opacity=".5"/><circle cx="65" cy="25" r="4" fill="currentColor"/><g transform="translate(215 115) rotate(-33 24 28) scale(.8)"><path d="M14 22V15a10 10 0 0 1 20 0v7" fill="none" stroke="currentColor" stroke-width="5"/><path d="M24 20C3 20 2 51 24 52c22-1 21-32 0-32" fill="currentColor"/></g></svg>`}
function nextApproach(){for(let i=0;i<draft().length;i++){let j=draft()[i].sets.findIndex(s=>!s.done);if(j>=0)return {i,j,e:draft()[i],s:draft()[i].sets[j]}}return null}
workout = function(){
  const ex=draft(),n=nextApproach(),done=completed(ex),all=ex.reduce((a,e)=>a+e.sets.length,0);
  const previous=n?db.sessions.filter(s=>s.date<selected).sort((a,b)=>b.date.localeCompare(a.date)).flatMap(s=>s.exercises.filter(e=>e.name===n.e.name)).flatMap(e=>e.sets.filter(s=>s.done))[0]:null;
  const journal=journalWorkout(),layout=journal.slice(journal.indexOf('<div class="layout">'));
  return `<div class="iron-heading"><div><h1>Твоя сила.<br>В действии.</h1><p>Тренировка с гирями · ${ex.length} упражнения</p></div><label class="iron-date">Дата тренировки<input aria-label="Дата текущей тренировки" id="focus-date" type="date" value="${selected}"></label></div><div class="iron-grid"><section class="iron-focus">${swingArt()}<div class="focus-top"><span class="focus-state">${n?'Текущий подход':'Все подходы выполнены'}</span><span>${done} / ${all}</span></div>${n?`<h2>${esc(n.e.name)}</h2><div class="muscles">${esc(catalog.find(c=>c.name===n.e.name)?.group||'Своя программа')} · подход ${n.j+1} из ${n.e.sets.length}</div><div class="focus-numbers"><label class="big-field"><input aria-label="Вес текущего подхода" id="focus-weight" type="number" step="0.5" min="0.5" max="200" value="${n.s.weight}"><span>кг · одна гиря</span></label><span class="multiply">×</span><label class="big-field"><input aria-label="Повторения текущего подхода" id="focus-reps" type="number" min="1" max="1000" value="${n.s.reps}"><span>повторений</span></label></div><div class="between"><label class="bell-select">Гирь в подходе<select id="focus-bells" aria-label="Гирь в текущем подходе"><option value="1" ${n.s.bells===1?'selected':''}>1</option><option value="2" ${n.s.bells===2?'selected':''}>2</option></select></label><p class="focus-prev">${previous?`Ранее: ${previous.weight} кг × ${previous.reps}`:'Первый результат — точка отсчёта'}</p></div><div class="focus-footer"><button class="primary" id="complete-current">Подход ${n.j+1} выполнен <span aria-hidden="true">↗</span></button><button class="text-btn" id="focus-technique">Техника</button></div>`:`<div class="no-next"><h2>Работа<br>сделана.</h2><p>Сохрани тренировку, чтобы увидеть результат в истории и на графике.</p><button class="primary" id="save-from-focus">Сохранить тренировку ↗</button></div>`}</section><section class="iron-metrics"><div><div class="metric-title">Поднято за тренировку</div><div class="ton-big" id="focus-tonnage">${fmt(totals(ex))}<small> кг</small></div><span class="muted">Тоннаж выполненных подходов</span><div class="set-segments" aria-label="${done} из ${all} подходов">${Array.from({length:all},(_,i)=>`<span class="${i<done?'filled':''}"></span>`).join('')}</div></div><div class="rule"></div><div class="metric-row"><span>Подходы</span><strong>${done}<small class="muted"> / ${all}</small></strong></div><div class="rule"></div><div class="metric-row"><span>Пульс</span><strong id="heart-value">${heartRate||'—'}<small class="muted"> уд/мин</small></strong></div><span class="muted" id="heart-status">${heartRate?'Датчик подключён':'Подключи датчик вверху экрана'}</span><div class="rule"></div><button class="secondary" id="open-rest">◷ Отдых · <span id="compact-timer">${timerText()}</span></button></section></div><div class="session-actions"><button class="text-btn" id="end-session">Завершить и сохранить</button><button class="text-btn" data-goto="program">Моя программа ↗</button></div>${measurementDue()?'<div class="iron-note"><span>В этом месяце ещё нет замеров тела.</span><button class="text-btn" data-goto="body">Записать замеры</button></div>':''}<details class="journal-details"><summary>Все упражнения и подходы <span class="muted">${ex.length} упражнения</span></summary>${layout}</details>`;
};
function readCurrent(){const n=nextApproach();if(!n)return null;for(const [key,id] of [['weight','focus-weight'],['reps','focus-reps'],['bells','focus-bells']]){const input=document.getElementById(id);if(!input.checkValidity()){input.reportValidity();return null}n.s[key]=+input.value}return n}
function gainFeedback(amount){lastGain=amount;const gain=document.createElement('div');gain.className='load-gain';gain.textContent=`+${fmt(amount)} кг`;document.body.append(gain);setTimeout(()=>gain.remove(),1400)}
function stopRest(){clearInterval(timerId);timerId=null;restPaused=true}
function startRest(){stopRest();seconds=90;restDeadline=Date.now()+90000;restPaused=false;timerId=setInterval(tickRest,200)}
function tickRest(){seconds=Math.max(0,Math.ceil((restDeadline-Date.now())/1000));updateTimer();if(!seconds){stopRest();updateTimer();toast('Отдых завершён — следующий подход');navigator.vibrate?.([180,80,180])}}
toggleTimer=function(){if(timerId){seconds=Math.max(0,Math.ceil((restDeadline-Date.now())/1000));stopRest()}else{if(!seconds)seconds=90;restDeadline=Date.now()+seconds*1000;restPaused=false;timerId=setInterval(tickRest,200)}updateTimer()};
updateTimer=function(){document.querySelectorAll('#timer-display,#rest-time,#compact-timer').forEach(e=>e.textContent=timerText());if($('#timer-toggle'))$('#timer-toggle').textContent=timerId?'Пауза':'Старт';if($('#rest-toggle'))$('#rest-toggle').textContent=timerId?'Пауза':'Продолжить';if($('#rest-fill'))$('#rest-fill').style.width=`${Math.min(100,seconds/90*100)}%`};
function openRest(gain=0){$('#modal-content').innerHTML=`<div class="rest-view"><div class="eyebrow">Восстанови дыхание</div><h2>Время отдыха</h2>${gain?`<div class="rest-gain">+${fmt(gain)} кг в твою копилку</div>`:''}<div class="timer" id="rest-time" role="timer" aria-label="Время отдыха">${timerText()}</div><div class="progress-track"><div id="rest-fill" style="width:${Math.min(100,seconds/90*100)}%"></div></div><div class="rest-controls"><button class="primary" id="rest-toggle">${timerId?'Пауза':'Продолжить'}</button><button class="secondary" id="rest-reset">Сброс</button></div><button class="text-btn" id="rest-skip">К следующему подходу ↗</button><p>Таймер продолжит работать, если закрыть окно.</p></div>`;if(!$('#modal').open)$('#modal').showModal();$('#rest-toggle').onclick=toggleTimer;$('#rest-reset').onclick=()=>{stopRest();seconds=90;updateTimer()};$('#rest-skip').onclick=()=>{stopRest();$('#modal').close();render()}}
function finishIron(){if(!completed(draft()))return toast('Сначала отметь выполненные подходы');stopRest();const session={date:selected,exercises:structuredClone(draft()),minutes:Math.round((Date.now()-trainingStart)/60000)};const index=db.sessions.findIndex(s=>s.date===selected);if(index>=0)db.sessions[index]=session;else db.sessions.push(session);save();const previous=db.sessions.filter(s=>s.date<selected).sort((a,b)=>b.date.localeCompare(a.date))[0];let diff=previous?totals(session.exercises)-totals(previous.exercises):null;$('#modal-content').innerHTML=`<div class="result-view"><div class="result-badge">СДЕЛАНО</div><h2>Сила в цифрах.</h2><div class="ton-big">${fmt(totals(session.exercises))}<small> кг</small></div><p>${completed(session.exercises)} подходов выполнено.<br>Тренировка за ${new Date(selected+'T12:00:00').toLocaleDateString('ru-RU')} сохранена.</p>${diff!==null?`<p>${diff>=0?'+':''}${fmt(diff)} кг к предыдущей тренировке<br><span class="muted">Общий тоннаж; программы могут различаться</span></p>`:''}<button class="primary" id="result-progress">Посмотреть прогресс ↗</button></div>`;if(!$('#modal').open)$('#modal').showModal();$('#result-progress').onclick=()=>{$('#modal').close();navigate('progress')};render()}
bind=function(){journalBind();if(page!=='workout')return;$('#focus-date').onchange=e=>{if(e.target.value){stopRest();selected=e.target.value;lastGain=0;render()}};const n=nextApproach();if(n){$('#focus-technique').onclick=()=>showInfo(catalog.find(e=>e.name===n.e.name)||n.e);['focus-weight','focus-reps','focus-bells'].forEach(id=>document.getElementById(id).onchange=()=>{if(readCurrent()){save();$('#focus-tonnage').innerHTML=`${fmt(totals(draft()))}<small> кг</small>`}});$('#complete-current').onclick=()=>{const current=readCurrent();if(!current)return;const amount=current.s.weight*current.s.reps*current.s.bells;current.s.done=true;save();render();gainFeedback(amount);if(nextApproach()){startRest();openRest(amount)}else{stopRest();toast('Все подходы выполнены. Сохрани тренировку.')}}}else $('#save-from-focus').onclick=finishIron;$('#end-session').onclick=finishIron;$('#finish').onclick=finishIron;$('#open-rest').onclick=()=>{if(!timerId&&seconds===90)startRest();openRest()};document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const [i,j]=b.dataset.check.split(','),s=draft()[i].sets[j];s.done=!s.done;save();render();if(s.done)gainFeedback(s.weight*s.reps*s.bells)})};
$('.brand').innerHTML=`${bellMark()}<b>ГИРЯ</b><small>ЖЕЛЕЗО + ЭНЕРГИЯ</small>`;
$('.brand').onclick=e=>{e.preventDefault();navigate('workout')};
$('.aside-bottom b').textContent='Сила — в действии.';
$('.aside-bottom p').textContent='Каждый подход считается.';

